class Solution {
    long long countAtMost(const vector<int>& nums, long long limit) {
        long long count = 0, sum = 0;
        int left = 0;
        for (int right = 0; right < (int)nums.size(); ++right) {
            sum += nums[right];
            while (sum > limit) {
                sum -= nums[left++];
            }
            count += right - left + 1;
        }
        return count;
    }
public:
    int kthSmallestSubarraySum(vector<int>& nums, int k) {
        long long lo = 1, hi = accumulate(nums.begin(), nums.end(), 0LL);
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            if (countAtMost(nums, mid) >= k) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int)lo;
    }
};
